#include <bits/stdc++.h>
using namespace std;
// (same packing logic as solution, but scan multiple W)
typedef pair<int,int> pii;
typedef vector<pii> Shape;
Shape applyTransform(const Shape& s,int R,int F){Shape r;for(auto[x,y]:s){if(F)x=-x;for(int i=0;i<R;i++){int nx=y,ny=-x;x=nx;y=ny;}r.push_back({x,y});}return r;}
struct OI{int R,F,bw,bh,normX,normY;vector<int>miny,maxy;};
vector<OI>getOI(const Shape&s){set<Shape>seen;vector<OI>res;for(int f=0;f<=1;f++)for(int r=0;r<4;r++){Shape t=applyTransform(s,r,f);int mx=INT_MAX,my=INT_MAX;for(auto[x,y]:t){mx=min(mx,x);my=min(my,y);}Shape n=t;for(auto&[x,y]:n){x-=mx;y-=my;}sort(n.begin(),n.end());if(!seen.insert(n).second)continue;OI o;o.R=r;o.F=f;o.normX=mx;o.normY=my;o.bw=o.bh=0;for(auto[x,y]:n){o.bw=max(o.bw,x+1);o.bh=max(o.bh,y+1);}o.miny.assign(o.bw,INT_MAX);o.maxy.assign(o.bw,INT_MIN);for(auto[x,y]:n){o.miny[x]=min(o.miny[x],y);o.maxy[x]=max(o.maxy[x],y);}res.push_back(move(o));}sort(res.begin(),res.end(),[](const OI&a,const OI&b){return a.bw<b.bw;});return res;}
int pack(const vector<vector<OI>>&AO,int n,int W,const vector<int>&ord){vector<int>sky(W,0);for(int idx:ord){int by=INT_MAX,bx=INT_MAX;const OI*bo=nullptr;for(const auto&oi:AO[idx]){if(oi.bw>W)continue;int lim=W-oi.bw;const int*sp=sky.data(),*mp=oi.miny.data();int bw=oi.bw;for(int px=0;px<=lim;px++){int py=0;bool bad=false;for(int cx=0;cx<bw;cx++){int v=sp[px+cx]-mp[cx];if(v>=by){bad=true;break;}if(v>py)py=v;}if(!bad&&(py<by||(py==by&&px<bx))){by=py;bx=px;bo=&oi;if(by==0)break;}}if(by==0&&bx==0)break;}if(!bo)return INT_MAX;const int*mp2=bo->maxy.data();int bw=bo->bw;for(int cx=0;cx<bw;cx++)if(mp2[cx]!=INT_MIN)sky[bx+cx]=max(sky[bx+cx],by+mp2[cx]+1);}return *max_element(sky.begin(),sky.end());}
int main(){int n;cin>>n;vector<Shape>pieces(n);long long S=0;for(int i=0;i<n;i++){int k;cin>>k;pieces[i].resize(k);S+=k;for(auto&[x,y]:pieces[i])cin>>x>>y;}vector<vector<OI>>AO(n);for(int i=0;i<n;i++)AO[i]=getOI(pieces[i]);vector<int>ord(n);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int a,int b){return pieces[a].size()>pieces[b].size();});int sq=(int)ceil(sqrt((double)S));for(int pct=70;pct<=400;pct+=5){int W=max(1,(int)round(sq*pct/100.0));int H=pack(AO,n,W,ord);if(H==INT_MAX)continue;printf("W=%d H=%d A=%lld fill=%.4f\n",W,H,(long long)W*H,(double)S/(W*H));}}
